/**
 * 全局图片懒加载
 *
 * 站点里大量曲绘 / 封面 / 卡面都是远程图片，一次性全部请求会白等带宽、拖慢首屏。
 * 这里用原生 loading="lazy"（浏览器自带的懒加载：图片接近视口才发起请求），
 * 通过一个全局 mixin 在每个组件挂载 / 更新后自动给子树里的 <img> 补上属性，
 * 因此不需要改动任何组件模板。
 *
 * 规则：
 *  - 组件自己写了 loading（或已经处理过的）不动，尊重组件写法；
 *  - 已经在视口内（或视口外一点点）的图片保持立即加载，避免拖慢首屏大图 / 图标；
 *  - 其余图片加 loading="lazy"，滚动到附近时浏览器再下载。
 */

const READY_ATTR = 'data-lazy-done'
const MARGIN = 200 // 视口外这个范围内也算“马上要看到”，保持立即加载

function isNearViewport(img) {
  const rect = img.getBoundingClientRect()
  const vh = window.innerHeight || document.documentElement.clientHeight || 0
  const vw = window.innerWidth || document.documentElement.clientWidth || 0
  return (
    rect.bottom > -MARGIN &&
    rect.top < vh + MARGIN &&
    rect.right > -MARGIN &&
    rect.left < vw + MARGIN
  )
}

function markImage(img) {
  if (!img || img.nodeType !== 1 || img.tagName !== 'IMG') return
  if (img.hasAttribute('loading') || img.hasAttribute(READY_ATTR)) return
  img.setAttribute(READY_ATTR, '')
  if (isNearViewport(img)) return
  img.setAttribute('loading', 'lazy')
}

/** 处理 root 子树里所有还没处理过的 <img>（root 自身是 img 时也包括它） */
export function markLazyImages(root) {
  if (!root || root.nodeType !== 1) return
  if (root.tagName === 'IMG') {
    markImage(root)
    return
  }
  if (!root.querySelectorAll) return
  const imgs = root.querySelectorAll('img:not([loading]):not([' + READY_ATTR + '])')
  for (let i = 0; i < imgs.length; i++) markImage(imgs[i])
}

export default {
  install(app) {
    app.mixin({
      mounted() {
        markLazyImages(this.$el)
      },
      updated() {
        // 列表刷新 / 翻页 / v-if 切回来时补上新出现的图片
        markLazyImages(this.$el)
      }
    })

    // mixin 覆盖不到的地方（多根节点组件、第三方直接插进 DOM 的图片）用观察器兜底
    if (typeof MutationObserver !== 'undefined' && typeof document !== 'undefined') {
      const observer = new MutationObserver((records) => {
        for (const record of records) {
          for (const node of record.addedNodes) {
            markLazyImages(node)
          }
        }
      })
      observer.observe(document.documentElement, { childList: true, subtree: true })
    }
  }
}
